package dev.blamspot.jcode.ext.pg

/**
 * The shared-memory shim, carried in the extension rather than fetched.
 *
 * Android kernels are built without CONFIG_SYSVIPC, so shmget returns ENOSYS and PostgreSQL dies
 * during initdb. This is an LD_PRELOAD shim reimplementing those calls on an anonymous memfd,
 * gzip'd and base64'd because a dex has no resources to keep a file in.
 *
 * AUTO-GENERATED from native/libandroshm.c — see native/README.md. Do not edit by hand.
 */
internal const val SHIM_GZ_BASE64: String =
    ""
